update public.products set description='Raw shelled groundnuts are uncooked peanut kernels with the outer pods removed, suitable for roasting, boiling, frying, groundnut paste, sauces and other preparations after appropriate cooking.', handling_protocols=array['Sort carefully and remove shrivelled, discoloured, moldy, insect-damaged or otherwise defective kernels.','Keep dry during storage and wash only immediately before cooking when the preparation requires it.','Cook or roast thoroughly before eating rather than treating the raw kernels as a ready-to-eat snack.','Discard moldy or musty-smelling kernels rather than trying to recover them by washing or roasting.']::text[], storage_tips=array['Store in a clean, dry, airtight or hermetic food-safe container away from humidity, sunlight and heat.','For best household quality, use within about 1–2 months when stored sealed in a cool, dry location.','Refrigerate or freeze for substantially longer storage where practical.','Discard nuts that become moldy, damp or musty, heavily insect-damaged or noticeably rancid/off-smelling.']::text[] where name='Raw Shelled Groundnuts' and category_id=(select id from public.product_categories where name='Tubers & Legumes');
update public.products set description='Roasted shelled groundnuts are cooked peanut kernels with the shells removed, offering the familiar roasted nutty flavour and crisp texture for snacking or use in meals, toppings and sauces.', handling_protocols=array['Keep protected from moisture, dirty hands, insects and cross-contamination after roasting.','Use clean, dry utensils when serving or repacking and keep the remaining product covered.','Discard kernels that are moldy, severely shrivelled, unusually discoloured or rancid-smelling.']::text[], storage_tips=array['Store in a clean airtight, moisture-resistant container away from sunlight and heat.','Do not leave roasted groundnuts open to humid air because moisture reduces crispness and accelerates deterioration.','For best quality at room temperature, use within about 3–4 weeks; refrigerate for longer storage.','Discard if moldy, damp, insect-infested or strongly rancid/paint-like in smell or taste.']::text[] where name='Roasted Groundnut (Shelled)' and category_id=(select id from public.product_categories where name='Tubers & Legumes');
update public.products set description='Roasted groundnuts with the pods intact are whole peanuts roasted in their shells, offering a traditional snack format where the shell is cracked open immediately before the kernels are eaten.', handling_protocols=array['Keep roasted pods clean, dry and protected from crushing.','Crack the shells only when ready to eat rather than shelling the whole batch in advance.','Discard pods or kernels showing visible mold, severe insect damage, unusual discoloration, wetness or an unpleasant rancid or musty smell.']::text[], storage_tips=array['Store in a clean, dry, well-sealed moisture-resistant container after the nuts have completely cooled.','Keep away from heat, sunlight and humid air.','For best quality, use within about 3–4 weeks at room temperature; refrigerate for longer storage.','Discard moldy, damp, heavily insect-damaged or strongly rancid-smelling nuts.']::text[] where name='Roasted Groundnut (With Shell)' and category_id=(select id from public.product_categories where name='Tubers & Legumes');;
